package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethodMap;
import com.fasterxml.jackson.databind.introspect.ClassIntrospector.MixInResolver;
import com.fasterxml.jackson.databind.util.Annotations;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.lang.annotation.Annotation;
import java.lang.reflect.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.ArgumentMatchers;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for _addMethodMixIns.
 * Since the method is protected and belongs to AnnotatedClass, 
 * we use a subclass or Mockito to access it.
 */
public class AnnotatedClass__addMethodMixIns_TriageGen1Test {

    // Mock classes for testing
    public static class TargetClass {
        public void existingMethod() {}
    }

    public static class MixInClass {
        public void mixInMethod() {} // Should be added to mixIns
        private void privateMethod() {} // Should be filtered by _isIncludableMemberMethod
    }

    public static class MaskingMixIn extends MixInClass {
        public void existingMethod() {} // Should trigger _addMixUnders because it exists in target
    }

    /**
     * A Testable subclass to expose protected methods and mock internal calls
     */
    private static class TestableAnnotatedClass extends AnnotatedClass {

        protected TestableAnnotatedClass(Class<?> cls, com.fasterxml.jackson.databind.introspect.AnnotationIntrospector aintr, com.fasterxml.jackson.databind.introspect.MixInResolver mir) {
            super(cls, aintr, mir);
        }

        @Override
        protected boolean _isIncludableMemberMethod(Method m) {
            // Simulate logic: ignore private methods
            return java.lang.reflect.Modifier.isPublic(m.getModifiers());
        }

        @Override
        protected AnnotatedMethod _constructMethod(Method m) {
            return mock(AnnotatedMethod.class);
        }

        @Override
        protected void _addMixUnders(Method src, AnnotatedMethod target) {
            // Implementation for testing
        }

        // Expose the protected method for testing
        public void call_addMethodMixIns(Class<?> targetClass, AnnotatedMethodMap methods,
                                        Class<?> mixInCls, AnnotatedMethodMap mixIns) {
            super._addMethodMixIns(targetClass, methods, mixInCls, mixIns);
        }

        // Mocking the _addMixUnders via spy if needed, but here we override
        protected boolean mixUndersCalled = false;
        @Override
        protected void _addMixUnders(Method src, AnnotatedMethod target) {
            mixUndersCalled = true;
        }
    }

    @Test
    public void test_addMethodMixIns_StandardFlow() throws Exception {
        // Setup
        com.fasterxml.jackson.databind.introspect.AnnotationIntrospector aintr = mock(com.fasterxml.jackson.databind.introspect.AnnotationIntrospector.class);
        com.fasterxml.jackson.databind.introspect.MixInResolver mir = mock(com.fasterxml.jackson.databind.introspect.MixInResolver.class);

        TestableAnnotatedClass annotatedClass = new TestableAnnotatedClass(TargetClass.class, aintr, mir);

        AnnotatedMethodMap methods = mock(AnnotatedMethodMap.class);
        AnnotatedMethodMap mixIns = mock(AnnotatedMethodMap.class);

        // Scenario 1: mixInMethod is not in target 'methods' map -> should call mixIns.add(_constructMethod(m))
        // Scenario 2: existingMethod is in target 'methods' map -> should call _addMixUnders

        Method mixInMethod = MixInClass.class.getMethod("mixInMethod");
        Method existingMethod = TargetClass.class.getMethod("existingMethod");
        AnnotatedMethod amForExisting = mock(AnnotatedMethod.class);

        when(methods.find(mixInMethod)).thenReturn(null);
        when(methods.find(existingMethod)).thenReturn(amForExisting);

        // We use MaskingMixIn to ensure we test inheritance and the "am != null" branch
        annotatedClass.call_addMethodMixIns(TargetClass.class, methods, MaskingMixIn.class, mixIns);

        // Verify mixInMethod (from parent) was added to mixIns
        verify(mixIns, atLeastOnce()).add(any(AnnotatedMethod.class));

        // Verify existingMethod (from subclass) triggered _addMixUnders
        // Since existingMethod is in MaskingMixIn and also in TargetClass (mocked in 'methods')
        // The logic: if (am != null) -> _addMixUnders
        // Note: In a real scenario, MaskingMixIn.existingMethod would be found in 'methods'
        // Here we simulate that by ensuring 'methods' returns an object for it.
    }

    @Test
    public void test_addMethodMixIns_FilterIncludable() throws Exception {
        com.fasterxml.jackson.databind.introspect.AnnotationIntrospector aintr = mock(com.fasterxml.jackson.databind.introspect.AnnotationIntrospector.class);
        com.fasterxml.jackson.databind.introspect.MixInResolver mir = mock(com.fasterxml.jackson.databind.introspect.MixInResolver.class);

        TestableAnnotatedClass annotatedClass = new TestableAnnotatedClass(TargetClass.class, aintr, mir);

        AnnotatedMethodMap methods = mock(AnnotatedMethodMap.class);
        AnnotatedMethodMap mixIns = mock(AnnotatedMethodMap.class);

        // MixInClass has a private method 'privateMethod'. 
        // Our TestableAnnotatedClass overrides _isIncludableMemberMethod to return false for private.
        annotatedClass.call_addMethodMixIns(TargetClass.class, methods, MixInClass.class, mixIns);

        // mixInMethod is public, so it should be processed.
        // privateMethod is private, so it should be skipped.
        // If privateMethod were processed, it would try to call methods.find(privateMethod).
        verify(methods, times(1)).find(any(Method.class)); 
    }

    @Test
    public void test_addMethodMixIns_WithMasking() throws Exception {
        com.fasterxml.jackson.databind.introspect.AnnotationIntrospector aintr = mock(com.fasterxml.jackson.databind.introspect.AnnotationIntrospector.class);
        com.fasterxml.jackson.databind.introspect.MixInResolver mir = mock(com.fasterxml.jackson.databind.introspect.MixInResolver.class);

        TestableAnnotatedClass annotatedClass = new TestableAnnotatedClass(TargetClass.class, aintr, mir);

        AnnotatedMethodMap methods = mock(AnnotatedMethodMap.class);
        AnnotatedMethodMap mixIns = mock(AnnotatedMethodMap.class);

        // MaskingMixIn has existingMethod(). 
        // We make sure 'methods' returns an AnnotatedMethod for it to trigger the 'am != null' branch.
        Method existingMethod = MaskingMixIn.class.getMethod("existingMethod");
        AnnotatedMethod am = mock(AnnotatedMethod.class);
        when(methods.find(existingMethod)).thenReturn(am);

        annotatedClass.call_addMethodMixIns(TargetClass.class, methods, MaskingMixIn.class, mixIns);

        // Verify _addMixUnders was called (via our boolean flag in TestableAnnotatedClass)
        assert(annotatedClass.mixUndersCalled);
    }
}
